local CrossbowMaker = {}
local PRODUCTS = {
    light_crossbow = { name = "Lahki samostrel", woodCost = 2, gutCost = 2, ironCost = 1, time = 3, cost = 60, attack = 12, durability = 22, description = "Lahki samostrel za hitro streljanje." },
    medium_crossbow = { name = "Srednji samostrel", woodCost = 3, gutCost = 2, ironCost = 1, time = 5, cost = 160, attack = 18, durability = 30, prestige = 2, description = "Srednji samostrel za pehoto." },
    steel_lath_crossbow = { name = "Jekleni samostrel", woodCost = 3, steelCost = 2, ironCost = 1, time = 7, cost = 380, attack = 26, durability = 42, prestige = 5, happiness = 1, description = "Samostrel z jekleno napetostjo." },
    arbalest = { name = "Arbalest", woodCost = 4, steelCost = 2, ironCost = 1, hornCost = 1, time = 9, cost = 800, attack = 34, durability = 55, prestige = 10, happiness = 2, description = "Težki arbalest z vitlom." },
    silver_decorated_crossbow = { name = "Srebrno okrašen samostrel", woodCost = 4, steelCost = 2, silverCost = 1, hornCost = 1, time = 11, cost = 1500, attack = 42, durability = 65, prestige = 18, happiness = 3, description = "Samostrel s srebrnim okrasjem." },
    royal_ceremonial_crossbow = { name = "Kraljevski slovesni samostrel", woodCost = 5, steelCost = 3, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, hornCost = 1, time = 16, cost = 3000, attack = 56, durability = 90, prestige = 55, happiness = 11, description = "Veliki kraljevski slovesni samostrel z zlatim in bisernim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Samostrelska delavnica", cost = { gold = 290, wood = 140 }, upkeep = 7, qualityBonus = 5 },
    forge = { name = "Samostrelska kovačija", cost = { gold = 950, wood = 220, stone = 250, iron = 8 }, upkeep = 22, qualityBonus = 18 },
    tillering_room = { name = "Ukrivljalnica", cost = { gold = 2000, wood = 300, stone = 400, silver = 25, steel = 8 }, upkeep = 48, qualityBonus = 30 },
    royal_crossbow_atelier = { name = "Kraljevski atelje samostrelov", cost = { gold = 8000, wood = 600, stone = 800, gold = 50, jewel = 20 }, upkeep = 150, qualityBonus = 55, prestigeBonus = 35 },
}
CrossbowMaker.woodStock = 18; CrossbowMaker.gutStock = 14; CrossbowMaker.ironStock = 12; CrossbowMaker.steelStock = 10; CrossbowMaker.hornStock = 8; CrossbowMaker.silverStock = 6; CrossbowMaker.goldStock = 6; CrossbowMaker.jewelStock = 6; CrossbowMaker.pearlStock = 4
CrossbowMaker.productStock = {}; CrossbowMaker.buildings = {}; CrossbowMaker.maker = nil; CrossbowMaker.activeMaking = {}; CrossbowMaker.totalProducts = 0; CrossbowMaker.dayTimer = 0
function CrossbowMaker.init() CrossbowMaker.woodStock=18; CrossbowMaker.gutStock=14; CrossbowMaker.ironStock=12; CrossbowMaker.steelStock=10; CrossbowMaker.hornStock=8; CrossbowMaker.silverStock=6; CrossbowMaker.goldStock=6; CrossbowMaker.jewelStock=6; CrossbowMaker.pearlStock=4; CrossbowMaker.productStock={}; CrossbowMaker.buildings={}; CrossbowMaker.maker=nil; CrossbowMaker.activeMaking={}; CrossbowMaker.totalProducts=0; CrossbowMaker.dayTimer=0; print("[CrossbowMaker] Royal Crossbow Maker System initialized (6 products, 4 buildings)") end
function CrossbowMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CrossbowMaker.maker={name=n or ("Samostrelar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Samostrelar najet: %s (spretnost: %d)",CrossbowMaker.maker.name,s),"success") end; return true end
function CrossbowMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CrossbowMaker.build(id) local ok,e=CrossbowMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CrossbowMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CrossbowMaker.getQualityBonus() local b=0; for _,bd in ipairs(CrossbowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CrossbowMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and CrossbowMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.gutCost and CrossbowMaker.gutStock<(d.gutCost or 0) then return false,"Premalo črevesja" end; if d.ironCost and CrossbowMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and CrossbowMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.hornCost and CrossbowMaker.hornStock<(d.hornCost or 0) then return false,"Premalo rogovja" end; if d.silverCost and CrossbowMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CrossbowMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CrossbowMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CrossbowMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CrossbowMaker.buildings==0 then return false,"Potrebna delavnica" end; if not CrossbowMaker.maker then return false,"Potreben samostrelar" end; return true end
function CrossbowMaker.make(pt,qty) qty=qty or 1; local ok,e=CrossbowMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then CrossbowMaker.woodStock=CrossbowMaker.woodStock-d.woodCost*qty end; if d.gutCost then CrossbowMaker.gutStock=CrossbowMaker.gutStock-d.gutCost*qty end; if d.ironCost then CrossbowMaker.ironStock=CrossbowMaker.ironStock-d.ironCost*qty end; if d.steelCost then CrossbowMaker.steelStock=CrossbowMaker.steelStock-d.steelCost*qty end; if d.hornCost then CrossbowMaker.hornStock=CrossbowMaker.hornStock-d.hornCost*qty end; if d.silverCost then CrossbowMaker.silverStock=CrossbowMaker.silverStock-d.silverCost*qty end; if d.goldCost then CrossbowMaker.goldStock=CrossbowMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CrossbowMaker.jewelStock=CrossbowMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CrossbowMaker.pearlStock=CrossbowMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CrossbowMaker.maker then t=math.max(1,t-math.floor(CrossbowMaker.maker.skill/12)) end; table.insert(CrossbowMaker.activeMaking,{id="crossbow_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CrossbowMaker.completeMaking(m) local q=1.0+(CrossbowMaker.getQualityBonus()/100); if CrossbowMaker.maker then q=q+(CrossbowMaker.maker.skill/180) end; q=math.min(2.0,q); CrossbowMaker.productStock[m.productType]=(CrossbowMaker.productStock[m.productType] or 0)+m.quantity; CrossbowMaker.totalProducts=CrossbowMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CrossbowMaker.maker then CrossbowMaker.maker.itemsMade=CrossbowMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then CrossbowMaker.maker.skill=math.min(100,CrossbowMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Samostrel izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"crossbow.completed",{productName=m.productName,attack=m.attack,durability=m.durability}) end end
function CrossbowMaker.update(dt) if not _G.state then return end; CrossbowMaker.dayTimer=CrossbowMaker.dayTimer+dt; if CrossbowMaker.dayTimer>=30 then CrossbowMaker.dayTimer=0; for i=#CrossbowMaker.activeMaking,1,-1 do local m=CrossbowMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CrossbowMaker.completeMaking(m); table.remove(CrossbowMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CrossbowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CrossbowMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CrossbowMaker.getStats() return {woodStock=CrossbowMaker.woodStock,gutStock=CrossbowMaker.gutStock,ironStock=CrossbowMaker.ironStock,steelStock=CrossbowMaker.steelStock,hornStock=CrossbowMaker.hornStock,silverStock=CrossbowMaker.silverStock,goldStock=CrossbowMaker.goldStock,jewelStock=CrossbowMaker.jewelStock,pearlStock=CrossbowMaker.pearlStock,productStock=CrossbowMaker.productStock,numBuildings=#CrossbowMaker.buildings,hasMaker=CrossbowMaker.maker~=nil,makerName=CrossbowMaker.maker and CrossbowMaker.maker.name or "—",makerSkill=CrossbowMaker.maker and CrossbowMaker.maker.skill or 0,activeMaking=#CrossbowMaker.activeMaking,totalProducts=CrossbowMaker.totalProducts} end
return CrossbowMaker
